import{_ as t,o as s,c as o,a0 as i}from"./chunks/framework.ZNXClGez.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/development/quick-start.md","filePath":"guide/development/quick-start.md"}'),a={name:"guide/development/quick-start.md"};function n(r,e,d,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This section will guide you through a quick setup process to get started with development and provide details on fully configuring your development environment.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Ensure the following software is installed on your system:</p><ul><li><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a></li><li><a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a> (<code>^22.13.0 || ^23.5.0 || &gt;=24.0.0</code>)</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-clone-the-repository" tabindex="-1">1. Clone the Repository <a class="header-anchor" href="#_1-clone-the-repository" aria-label="Permalink to &quot;1. Clone the Repository&quot;">​</a></h3><p>Clone the Authup repository to a local directory using Git:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/authup/authup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authup</span></span></code></pre></div><h3 id="_2-install-dependencies" tabindex="-1">2. Install Dependencies <a class="header-anchor" href="#_2-install-dependencies" aria-label="Permalink to &quot;2. Install Dependencies&quot;">​</a></h3><p>Install all required (dev-) dependencies for the monorepo.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span></span></code></pre></div><h3 id="_3-start-the-development-servers" tabindex="-1">3. Start the Development Servers <a class="header-anchor" href="#_3-start-the-development-servers" aria-label="Permalink to &quot;3. Start the Development Servers&quot;">​</a></h3><p>Build once, then start the one dev loop from the repository root:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>This runs <code>authup dev</code>. It is EXPERIMENTAL, and it is exactly <code>authup start</code> (server-core plus every enabled console on one listener), except that every console whose package resolves to a SOURCE checkout is served through a vite dev server with hot module replacement instead of from its built <code>dist/</code>. In this workspace that is all three consoles. Because everything stays on one origin, the dev loop signs in with the same <code>HttpOnly</code> session cookie a served console uses in production, not the standalone browser authorization-code flow.</p><p>The workspace additionally runs <code>server-core</code> itself from its TypeScript source (<code>ts-node/esm</code> plus the <code>authup-source</code> export condition, no build step), so an edit there needs a restart, not a rebuild.</p><div class="danger custom-block"><p class="custom-block-title">It is a development command, and it refuses production</p><p><code>authup dev</code> starts a vite dev server with a file watcher and a filesystem reader alongside the API, on the API&#39;s own listener, which binds <code>HOST</code> (<code>0.0.0.0</code> in the container). It therefore <strong>refuses to start when the resolved environment is production</strong> (<code>env</code> in <code>authup.yml</code>, or <code>NODE_ENV</code>), and tells you to run <code>authup start</code> instead. Do not work around the refusal.</p><p>The refusal is the control, not the absence of source. A package installed from npm ships <code>files: [&quot;dist&quot;]</code> and carries no <code>vite.config.ts</code>, so <code>authup dev</code> there serves every console from <code>dist/</code> exactly like <code>start</code> and says so. <strong>The published container image is the exception</strong>: it is built by copying the whole repository in and running <code>npm ci</code> without pruning, so it holds every source checkout and every devDependency, and <code>authup dev</code> inside it would find three source checkouts to serve. That is precisely what the production refusal exists to stop.</p></div><ul><li><strong>Backend + every console</strong> <code>http://localhost:3000/</code></li><li><strong>Admin console</strong> <code>http://localhost:3000/console/admin</code></li><li><strong>Account console</strong> <code>http://localhost:3000/console/account</code></li><li><strong>Auth console</strong> (login, <code>/register</code>, <code>/activate</code>, ...) <code>http://localhost:3000/console/auth/authorize</code></li><li><strong>Swagger-Docs</strong> <code>http://localhost:3000/docs</code></li><li><strong>Prometheus-Metrics</strong> <code>http://localhost:3000/metrics</code></li></ul><p>Each console&#39;s vite dev server opens its own hot-module-replacement websocket: 24678 (auth), 24679 (admin), 24680 (account). If one of those ports is already taken, the command refuses to start and names it, rather than coming up with that console silently un-hot; the usual cause is another <code>authup dev</code> still running.</p><p>Two things the dev servers deliberately will not do, because they ride the API&#39;s own listener rather than loopback. They refuse to read the database, <code>authup.yml</code>, any <code>.env</code> and anything under a <code>writable/</code> directory over vite&#39;s <code>/@fs/</code> route, and they answer 404 on vite&#39;s <code>__open-in-editor</code> endpoint, which otherwise spawns an editor process for any URL a visited page can request.</p><p>What is hot, and what still needs a restart or a rebuild:</p><table tabindex="0"><thead><tr><th>Edited</th><th>Effect</th></tr></thead><tbody><tr><td><code>apps/client-*-console/src/**</code></td><td>Hot module replacement</td></tr><tr><td><code>packages/client-web-kit/src/**</code>, the two theme packages</td><td>Hot module replacement</td></tr><tr><td><code>apps/server-core/src/**</code></td><td>No build; restart the process</td></tr><tr><td><code>apps/authup/src/**</code></td><td>No build; restart the process</td></tr><tr><td><code>packages/server-*</code>, <code>packages/kit</code>, <code>packages/errors</code>, the console services</td><td><code>npm run build -w &lt;workspace&gt;</code> required</td></tr></tbody></table><p>The last row is the honest limit: <code>ts-node</code> applies no tsconfig <code>paths</code> at runtime, so those packages still resolve to their built <code>dist/</code>. The first two rows are also why every console&#39;s vite config aliases <code>@authup/client-web-kit</code> (and the two theme packages) to source: one edit there hot-updates every console that imports it, the server-rendered auth pages included. That is the single biggest practical reason to use <code>npm run dev</code> over building each package by hand.</p><p>To work on one console alone, on its own origin, run its own dev server instead:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VITE_API_URL=http://localhost:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/client-admin-console</span></span></code></pre></div><p>It gives hot module replacement against the running backend, but it costs fidelity: served on a different origin (<code>http://localhost:3010</code> for the admin console) than the API, it signs in with the standalone browser authorization-code (PKCE) flow rather than the cookie-session credential a served console uses in production.</p><p>You can start working with the application or begin making contributions to the project!</p>`,28)])])}const k=t(a,[["render",n]]);export{u as __pageData,k as default};
